from pathlib import Path
import re
for page,count in [(10,7),(11,5)]:
    for line in Path(f'tmp/pdfs/page-{page:02d}.txt').read_text().splitlines():
        if not re.match(r'\\s*(?:mParamanu|Paramanu|Bloom|Sarvam|OpenHathi|Airavata)',line):
            continue
        numbers=[float(x) for x in re.findall(r'\\d+\\.\\d+',line)]
        if page==10 and len(numbers)>=7:
            vals=numbers[-7:]
        elif page==11 and len(numbers)>=5:
            vals=numbers[-5:]
        else:
            continue
        mean=sum(vals[:-1])/len(vals[:-1])
        if abs(mean-vals[-1])>0.02:
            print(line.strip())
            print('Computed mean:',round(mean,4),'Reported mean:',vals[-1])
